  2417  pdf_xref_entry *
  2418  pdf_cache_object(fz_context *ctx, pdf_document *doc, int num)
  2419  {
  2420          pdf_xref_entry *x;
  2421          int rnum, rgen, try_repair;
  2422
  2423          fz_var(try_repair);
  2424
  2425          if (num <= 0 || num >= pdf_xref_len(ctx, doc))
  2426                  fz_throw(ctx, FZ_ERROR_GENERIC, "object out of range (%d 0 R); xref size %d", num, pdf_xref_len(ctx, doc));
  2427
  2428  object_updated:
  2429          try_repair = 0;
  2430          rnum = num;
  2431
  2432          x = pdf_get_xref_entry(ctx, doc, num);
  2433          if (x == NULL)
  2434                  fz_throw(ctx, FZ_ERROR_GENERIC, "cannot find object in xref (%d 0 R)", num);
  2435
  2436          if (x->obj != NULL)
  2437                  return x;
  2438
  2439          if (x->type == 'f')
  2440          {
  2441                  x->obj = PDF_NULL;
  2442          }
  2443          else if (x->type == 'n')
  2444          {
  2445                  fz_seek(ctx, doc->file, x->ofs, SEEK_SET);
  2446
  2447                  fz_try(ctx)
  2448                  {
  2449                          x->obj = pdf_parse_ind_obj(ctx, doc, doc->file,
  2450                                          &rnum, &rgen, &x->stm_ofs, &try_repair);
  2451                  }
  2452                  fz_catch(ctx)
  2453                  {
  2454                          if (!try_repair || fz_caught(ctx) == FZ_ERROR_TRYLATER)
  2455                                  fz_rethrow(ctx);
  2456                  }
  2457
  2458                  if (!try_repair && rnum != num)
  2459                  {
  2460                          pdf_drop_obj(ctx, x->obj);
  2461                          x->type = 'f';
  2462                          x->ofs = -1;
  2463                          x->gen = 0;
  2464                          x->num = 0;
  2465                          x->stm_ofs = 0;
  2466                          x->obj = NULL;
  2467                          try_repair = (doc->repair_attempted == 0);
  2468                  }
  2469
  2470                  if (try_repair)
  2471                  {
  2472  perform_repair:
  2473                          fz_try(ctx)
  2474                          {
  2475                                  pdf_repair_xref(ctx, doc);
  2476                                  pdf_prime_xref_index(ctx, doc);
  2477                                  pdf_repair_obj_stms(ctx, doc);
  2478                                  pdf_repair_trailer(ctx, doc);
  2479                          }
  2480                          fz_catch(ctx)
  2481                          {
  2482                                  fz_rethrow_if(ctx, FZ_ERROR_TRYLATER);
  2483                                  fz_rethrow_if(ctx, FZ_ERROR_REPAIRED);
  2484                                  if (rnum == num)
  2485                                          fz_throw(ctx, FZ_ERROR_GENERIC, "cannot parse object (%d 0 R)", num);
  2486                                  else
  2487                                          fz_throw(ctx, FZ_ERROR_GENERIC, "found object (%d 0 R) instead of (%d 0 R)", rnum, num);
  2488                          }
  2489                          goto object_updated;
  2490                  }
  2491
  2492                  if (doc->crypt)
  2493                          pdf_crypt_obj(ctx, doc->crypt, x->obj, x->num, x->gen);
  2494          }
  2495          else if (x->type == 'o')
  2496          {
  2497                  if (!x->obj)
  2498                  {
  2499                          pdf_xref_entry *orig_x = x;
  2500                          orig_x->type = 'O'; /* Mark this node so we know we're recursing. */
  2501                          fz_try(ctx)
  2502                                  x = pdf_load_obj_stm(ctx, doc, x->ofs, &doc->lexbuf.base, num);
  2503                          fz_always(ctx)
  2504                                  orig_x->type = 'o'; /* Not recursing any more. */
  2505                          fz_catch(ctx)
  2506                                  fz_rethrow(ctx);
  2507                          if (x == NULL)
  2508                                  fz_throw(ctx, FZ_ERROR_GENERIC, "cannot load object stream containing object (%d 0 R)", num);
  2509                          if (!x->obj)
  2510                          {
  2511                                  x->type = 'f';
  2512                                  orig_x->type = 'f';
  2513                                  if (doc->repair_attempted)
  2514                                          fz_throw(ctx, FZ_ERROR_GENERIC, "object (%d 0 R) was not found in its object stream", num);
  2515                                  goto perform_repair;
  2516                          }
  2517                  }
  2518          }
  2519          else if (doc->hint_obj_offsets && read_hinted_object(ctx, doc, num))
  2520          {
  2521                  goto object_updated;
  2522          }
  2523          else if (doc->file_length && doc->linear_pos < doc->file_length)
  2524          {
  2525                  fz_throw(ctx, FZ_ERROR_TRYLATER, "cannot find object in xref (%d 0 R) - not loaded yet?", num);
  2526          }
  2527          else
  2528          {
  2529                  fz_throw(ctx, FZ_ERROR_GENERIC, "cannot find object in xref (%d 0 R)", num);
  2530          }
  2531
  2532          pdf_set_obj_parent(ctx, x->obj, num);
  2533          return x;
  2534  }
