  2544  pdf_resolve_indirect(fz_context *ctx, pdf_obj *ref)
  2545  {
  2546          if (pdf_is_indirect(ctx, ref))
  2547          {
  2548                  pdf_document *doc = pdf_get_indirect_document(ctx, ref);
  2549                  int num = pdf_to_num(ctx, ref);
  2550                  pdf_xref_entry *entry;
  2551
  2552                  if (!doc)
  2553                          return NULL;
  2554                  if (num <= 0)
  2555                  {
  2556                          fz_warn(ctx, "invalid indirect reference (%d 0 R)", num);
  2557                          return NULL;
  2558                  }
  2559
  2560                  fz_try(ctx)
  2561                          entry = pdf_cache_object(ctx, doc, num);
  2562                  fz_catch(ctx)
  2563                  {
  2564                          fz_rethrow_if(ctx, FZ_ERROR_TRYLATER);
  2565                          fz_rethrow_if(ctx, FZ_ERROR_REPAIRED);
  2566                          fz_warn(ctx, "cannot load object (%d 0 R) into cache", num);
  2567                          return NULL;
  2568                  }
  2569
  2570                  ref = entry->obj;
  2571          }
  2572          return ref;
  2573  }
