  2575  pdf_obj *
  2576  pdf_resolve_indirect_chain(fz_context *ctx, pdf_obj *ref)
  2577  {
  2578          int sanity = 10;
  2579
  2580          while (pdf_is_indirect(ctx, ref))
  2581          {
  2582                  if (--sanity == 0)
  2583                  {
  2584                          fz_warn(ctx, "too many indirections (possible indirection cycle involving %d 0 R)", pdf_to_num(ctx, ref));
  2585                          return NULL;
  2586                  }
  2587
  2588                  ref = pdf_resolve_indirect(ctx, ref);
  2589          }
  2590
  2591          return ref;
  2592  }
