  2610          if (xref == NULL)
  2611                  return 0; /* no local xref present */
  2612
  2613          num = pdf_to_num(ctx, obj);
  2614
  2615          /* Local xrefs only ever have 1 section, and it should be solid. */
  2616          sub = xref->subsec;
  2617          if (num >= sub->start && num < sub->start + sub->len)
  2618                  return sub->table[num - sub->start].type != 0;
  2619
  2620          return 0;
  2621  }
